actions.script:
Map toolMap = [:]

// 1. DIRECT SERVICE INSPECTION FOR org.moqui.ai.mcp.* SERVICES
def serviceFacade = ec.factory.serviceFacade
def knownServices = serviceFacade.getKnownServiceNames()

for (String serviceName in knownServices) {
    if (serviceName.startsWith("org.moqui.ai.mcp.")) {
        def sd = serviceFacade.getServiceDefinition(serviceName)
        if (sd != null) {
            def parts = serviceName.split("\\.")
            def rawName = parts[parts.length - 1].replace("#", "_")
            def cleanMethodName = rawName.replaceAll("([a-z])([A-Z])", '$1_$2').toLowerCase()

            def description = sd.serviceNode.attribute("description") ?: sd.serviceNode.first("description")?.getText() ?: "MCP tool for ${serviceName}"

            Map propertiesMap = [:]
            List requiredList = []

            sd.inParameterNameList.each { paramName ->
                def paramInfo = sd.inParameterInfoMap.get(paramName)
                if (paramInfo != null) {
                    def paramNode = paramInfo.parameterNode
                    boolean isInternal = paramNode.attribute("internal") == "true" || paramNode.attribute("scope") == "context"

                    if (!isInternal) {
                        def rawDesc = paramNode.attribute("description") ?: paramNode.first("description")?.getText() ?: paramName
                        def paramType = "string"

                        if (paramInfo.parmClass != null) {
                            String sName = paramInfo.parmClass.simpleName.toLowerCase()
                            if (sName.contains("int") || sName.contains("long")) paramType = "integer"
                            else if (sName.contains("bool")) paramType = "boolean"
                            else if (sName.contains("list") || sName.contains("set")) paramType = "array"
                            else if (sName.contains("map")) paramType = "object"
                        }

                        // 🎯 ENFORCE STRICT CANONICAL FORMAT GUIDANCE
                        String enhancedDesc = rawDesc
                        if (paramName.equalsIgnoreCase("artifactUri") || paramName.equalsIgnoreCase("targetScreenUri")) {
                            enhancedDesc += " (Required format: 'component://<componentName>/screen/<path>.xml')"
                        }

                        propertiesMap[paramName] = [
                            type: paramType,
                            description: enhancedDesc
                        ]

                        // Ensure required attributes are strictly captured
                        if (paramNode.attribute("required") == "true") {
                            requiredList.add(paramName)
                        }
                    }
                }
            }

            // Build rigid, explicit JSON schema definition
            toolMap[cleanMethodName] = [
                name: cleanMethodName,
                command: "/" + cleanMethodName.replace("_", "-"),
                serviceName: serviceName,
                title: cleanMethodName.replace("_", " ").capitalize(),
                description: description.trim() + " NOTE: Pass exact parameter names matching the schema. Execute once per atomic item.",
                inputSchema: [
                    type: "object",
                    properties: propertiesMap,
                    required: requiredList
                ]
            ]
        }
    }
}

// 2. OPTIONAL: QUERY moqui-mcp CATALOG
try {
    def mcpRes = ec.service.sync().name("McpServices.list#Tools").call()
    def mcpToolsList = mcpRes?.result?.tools ?: mcpRes?.tools ?: []

    mcpToolsList.each { mcpTool ->
        String tName = mcpTool.name
        if (tName && !toolMap.containsKey(tName)) {
            toolMap[tName] = [
                name: tName,
                command: "/" + tName.replace("_", "-"),
                serviceName: "McpServices.mcp#ToolsCall",
                isMcpWrapper: true,
                title: tName.replace("_", " ").capitalize(),
                description: mcpTool.description ?: "moqui-mcp tool",
                inputSchema: mcpTool.inputSchema ?: [type: "object", properties: [:]]
            ]
        }
    }
} catch (Exception ex) {
    ec.logger.warn("⚠️ Error inspecting McpServices.list#Tools catalog: " + ex.message)
}

context.tools = new ArrayList(toolMap.values())

Map callParams = parameters ?: [:]

if (serviceName == "McpServices.mcp#ToolsCall") {
    String actualToolName = toolName ?: callParams.remove("toolName") ?: callParams.remove("name")
    Map result = ec.service.sync().name("McpServices.mcp#ToolsCall").parameters([
        name: actualToolName,
        arguments: callParams
    ]).call()
    context.putAll(result?.result ?: result ?: [:])
    return
}

if (!serviceName.startsWith("org.moqui.ai.mcp.")) {
    ec.message.addError("Unauthorized service execution: " + serviceName)
    return
}

Map result = ec.service.sync().name(serviceName).parameters(callParams).call()
context.putAll(result)
